/* The museum's movement and visitor interactions. */
(()=>{
const reduceQuery=matchMedia('(prefers-reduced-motion: reduce)');
let motion= !reduceQuery.matches, theme='day', tourTimer=null, tourRunning=false, pointerFrame=0;
const toolbar=document.createElement('div');toolbar.className='experience-controls';toolbar.innerHTML=`<button id="atmosphere" aria-expanded="false" aria-controls="atmosphere-panel">◐ <span>Atmosphere</span></button><button id="motion-toggle" aria-pressed="${motion}">✳ <span>Motion ${motion?'on':'off'}</span></button><button id="visitor-stamp">◉ <span>Visitor stamp</span></button>`;document.body.append(toolbar);
const panel=document.createElement('div');panel.id='atmosphere-panel';panel.hidden=true;panel.innerHTML='<span class="eyebrow">SET THE MOOD</span><p>A different light. The same memories.</p><div><button data-light="day" aria-pressed="true">☀<span>Daylight</span></button><button data-light="golden" aria-pressed="false">◒<span>Golden hour</span></button><button data-light="night" aria-pressed="false">☾<span>After hours</span></button></div>';document.body.append(panel);
function applyMotion(){document.body.classList.toggle('still-museum',!motion);$('#motion-toggle').setAttribute('aria-pressed',String(motion));$('#motion-toggle span').textContent=`Motion ${motion?'on':'off'}`;if(!motion){main.getAnimations({subtree:true}).forEach(a=>a.cancel());main.style.setProperty('--px','0');main.style.setProperty('--py','0')}}
$('#motion-toggle').onclick=()=>{motion=!motion;applyMotion()};reduceQuery.addEventListener('change',e=>{motion=!e.matches;applyMotion()});applyMotion();
$('#atmosphere').onclick=()=>{panel.hidden=!panel.hidden;$('#atmosphere').setAttribute('aria-expanded',String(!panel.hidden))};panel.querySelectorAll('[data-light]').forEach(b=>b.onclick=()=>{theme=b.dataset.light;document.body.dataset.light=theme;panel.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){panel.hidden=true;$('#atmosphere').setAttribute('aria-expanded','false');stopTour()}});
let lastFocus;
$('#visitor-stamp').onclick=()=>{lastFocus=document.activeElement;stopTour();const d=document.createElement('dialog');d.className='stamp-dialog';d.setAttribute('aria-label','Your museum visitor stamp');const date=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});d.innerHTML=`<button class="detail-close" aria-label="Close visitor stamp">×</button><span class="eyebrow">A LITTLE SOMETHING TO KEEP</span><div class="stamp-mark"><span>MUSEUM OF YOU</span><strong>YOU<br>WERE<br>HERE.</strong><span>${esc(date)}</span></div><h2>Thanks for stopping by.</h2><p>Every visit is another way of remembering.</p><button class="stamp-done">Back to exploring ↗</button>`;document.body.append(d);d.querySelectorAll('button').forEach(b=>b.onclick=()=>d.close());d.addEventListener('close',()=>{d.remove();lastFocus?.focus()});d.showModal()};
function stopTour(){clearInterval(tourTimer);tourTimer=null;tourRunning=false;const b=$('#guided-tour');if(b){b.textContent='▷ Guided tour';b.setAttribute('aria-pressed','false')}}
function toggleTour(){if(tourRunning){stopTour();return}if(!activeExhibition?.objects.length)return;tourRunning=true;const b=$('#guided-tour');b.textContent='Ⅱ Pause tour';b.setAttribute('aria-pressed','true');tourTimer=setInterval(()=>{if(document.hidden||document.querySelector('dialog[open]'))return;if(!document.body.classList.contains('in-exhibition')||roomIndex>=activeExhibition.objects.length-1){stopTour();return}view(activeExhibition.id,roomIndex+1)},6500)}
function enhance(){const space=$('.museum-space');if(!space)return;
space.insertAdjacentHTML('beforeend',`<div class="light-beams" aria-hidden="true"></div><div class="museum-dust" aria-hidden="true">${Array.from({length:18},(_,i)=>`<i style="--x:${(i*37)%100}%;--y:${(i*23)%90}%;--d:${10+i%7}s;--delay:-${i*.73}s"></i>`).join('')}</div><div class="room-vignette" aria-hidden="true"></div>`);
if(document.body.classList.contains('in-exhibition')){const e=activeExhibition;const controls=$('.walk-controls');if(controls&&e.objects.length){controls.insertAdjacentHTML('afterend',`<div class="gallery-mini-map" aria-label="Exhibition objects">${e.objects.map((o,i)=>`<button aria-label="Go to ${esc(o.title||'object '+(i+1))}" aria-current="${i===roomIndex?'step':'false'}" data-room-index="${i}"><span></span></button>`).join('')}</div><button id="guided-tour" aria-pressed="${tourRunning}">${tourRunning?'Ⅱ Pause tour':'▷ Guided tour'}</button>`);main.querySelectorAll('[data-room-index]').forEach(b=>b.onclick=()=>{stopTour();view(e.id,Number(b.dataset.roomIndex))});$('#guided-tour').onclick=toggleTour}if(motion){space.animate([{opacity:.25,transform:'scale(1.035)'},{opacity:1,transform:'scale(1)'}],{duration:750,easing:'cubic-bezier(.2,.7,.2,1)'})}}
else{stopTour();space.insertAdjacentHTML('beforeend',`<div class="kinetic-sculpture" aria-hidden="true"><div class="sculpture-thread"></div><div class="orbit orbit-one"><i></i></div><div class="orbit orbit-two"><i></i></div><div class="sculpture-core">✳</div><span>THE ART OF BEING YOU</span></div><div class="floor-wayfinding" aria-hidden="true"><span>01</span><i>GALLERIES &nbsp; ↗</i></div>`)}
main.querySelectorAll('.doorway,.framed-work,.wall-label,.room-list button').forEach(b=>{b.addEventListener('pointerenter',()=>b.classList.add('is-hovered'));b.addEventListener('pointerleave',()=>b.classList.remove('is-hovered'))});
}
const observer=new MutationObserver(enhance);observer.observe(main,{childList:true});if($('.museum-space'))enhance();
main.addEventListener('pointermove',e=>{if(!motion||e.pointerType==='touch'||pointerFrame)return;pointerFrame=requestAnimationFrame(()=>{pointerFrame=0;main.style.setProperty('--px',((e.clientX/innerWidth)-.5).toFixed(3));main.style.setProperty('--py',((e.clientY/innerHeight)-.5).toFixed(3))})});main.addEventListener('pointerleave',()=>{main.style.setProperty('--px','0');main.style.setProperty('--py','0')});
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('page-hidden',document.hidden));
})();
